@push('scripts')<script>
const tm=bootstrap.Modal.getOrCreateInstance('#trainingModal'),tf=document.getElementById('trainingForm'),method=document.getElementById('trainingMethod');
function fillTraining(t=null){tf.reset();method.disabled=!t;tf.action=t?@json(url('/trainings'))+'/'+t.id:@json(route('trainings.store'));document.getElementById('trainingTitle').textContent=t?'Eğitimi Düzenle':'Yeni Eğitim';document.getElementById('trainingName').value=t?.name??'';document.getElementById('trainingDescription').value=t?.description??'';document.getElementById('trainingDuration').value=t?.duration_minutes??'';}
document.getElementById('addTraining').addEventListener('click',()=>fillTraining());document.querySelectorAll('.edit-training').forEach(b=>b.addEventListener('click',()=>{fillTraining({id:b.dataset.id,name:b.dataset.name,description:b.dataset.description,duration_minutes:b.dataset.durationMinutes});tm.show()}));
</script>@endpush
